L3_1.m_Pos = "C"
L3_1.m_Talk_KOREA = "아시다시피, 관리국에서는 정기적으로 태스크포스 컨퍼런스를 주최합니다."
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "ご存知のとおり、管理局では定期的にタスクフォースコンファレンスを主催しています。"
L3_1.m_Talk_ENG = "As you know, the Administration periodically holds a TASKFORCE conference."
L3_1.m_Talk_TWN = "老闆，你也知道管理局會定期舉行特遣勢力會議。"
L3_1.m_Talk_THA = "อย่างที่คุณรู้นะ องค์การบริหารโลกจัดการประชุมทาสก์ฟอร์สเป็นระยะ"
L3_1.m_Talk_VTN = "Như anh đã biết, Cục Quản Lý tổ chức định kỳ hội nghị TASKFORCE."
L3_1.m_Talk_SCN = "你也知道管理局会定期召开特遣势力会议。"
L3_1.m_Talk_DEU = "As you know, the Administration periodically holds a TASKFORCE conference."
L3_1.m_Talk_FRA = "As you know, the Administration periodically holds a TASKFORCE conference."
L4_1 = {}
L4_1.m_CutScenKey_Talk = "COUNTERCASE_ALPHA_JIA_NORMAL_4@4#Talk"
L4_1.m_CutScenProcessKey = 4
L4_1.m_CutScenID = 31414
L4_1.m_CutScenStrID = "COUNTERCASE_ALPHA_JIA_NORMAL_4"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L4_1.m_Pos = "C"
L4_1.m_Talk_KOREA = "그리고 정식으로 등록된 태스크포스라면, 컨퍼런스에 참가할 수 있는 초대권이 주어지죠."
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "そして正式に登録されているタスクフォースであれば、コンファレンスに参加できる招待状が送られます。"
L4_1.m_Talk_ENG = "Invitations are given to every officially registered TASKFORCE."
L4_1.m_Talk_TWN = "而且會邀請正式登記的特遣勢力參與會議。"
L4_1.m_Talk_THA = "คำเชิญจะถูกส่งไปยังทาสก์ฟอร์สที่ลงทะเบียนแล้วทั้งหมด"
L4_1.m_Talk_VTN = "Mọi TASKFORCE đã đăng ký chính thức đều có thư mời."
L4_1.m_Talk_SCN = "只要是正式登记的特遣势力就有资格参加。"
L4_1.m_Talk_DEU = "Invitations are given to every officially registered TASKFORCE."
L4_1.m_Talk_FRA = "Invitations are given to every officially registered TASKFORCE."
L5_1 = {}
L5_1.m_CutScenKey_Talk = "COUNTERCASE_ALPHA_JIA_NORMAL_4@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 31414
L5_1.m_CutScenStrID = "COUNTERCASE_ALPHA_JIA_NORMAL_4"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L5_1.m_Pos = "C"
L5_1.m_Talk_KOREA = "태스크포스의 업계 동향이라든지, 다른 회사 대표들 간 인맥을 쌓는 등…"
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "タスクフォース業界の動向を探り、他社の代表と人脈を作るなど……"
L5_1.m_Talk_ENG = "You can find out what’s going on in the TASKFORCE industry, make connections with other company presidents..."
L5_1.m_Talk_TWN = "在會議中不僅可以知道特遣勢力業界的最新動態，也可以和其他公司的老闆交流，累積人脈…"
L5_1.m_Talk_THA = "คุณสามารถดูได้ว่าเกิดอะไรขึ้นในอุตสาหกรรมทาสก์ฟอร์ส สร้างเครือข่ายกับประธานบริษัทอื่นๆ..."
L5_1.m_Talk_VTN = "Anh có thể tìm hiểu mọi diễn biến trong ngành TASKFORCE, kết nối với chủ tịch các công ty khác..."
L5_1.m_Talk_SCN = "参加会议不仅可以了解特遣势力的业界动向，还能结识其他公司高层，积累人脉……"
L5_1.m_Talk_DEU = "You can find out what’s going on in the TASKFORCE industry, make connections with other company presidents..."
L5_1.m_Talk_FRA = "You can find out what’s going on in the TASKFORCE industry, make connections with other company presidents..."
