L17_1.m_Talk_THA = "CEO ต้องเป็นผู้เข้าร่วมการประชุมค่ะ นั่นคือกฎ"
L17_1.m_Talk_VTN = "CEO phải tham dự hội nghị. Đó là quy định."
L17_1.m_Talk_SCN = "会议必须由公司代表参加，别人不可以代替出席。"
L17_1.m_Talk_DEU = "The CEO has to participate the conference. It’s the rule."
L17_1.m_Talk_FRA = "The CEO has to participate the conference. It’s the rule."
