L20_1 = {}
L20_1.m_CutScenKey_Talk = "COUNTERCASE_ALPHA_JIA_NORMAL_4@20#Talk"
L20_1.m_CutScenProcessKey = 20
L20_1.m_CutScenID = 31414
L20_1.m_CutScenStrID = "COUNTERCASE_ALPHA_JIA_NORMAL_4"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_Face = "UNIT_IDLE"
L20_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L20_1.m_Pos = "L"
L20_1.m_Talk_KOREA = "따라서 이번 주말 일정을 비워 두셨으면 합니다만?"
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "したがって、今週末は予定を空けておいてください。"
L20_1.m_Talk_ENG = "So I want you to attend the conference this weekend."
L20_1.m_Talk_TWN = "所以，希望這週末老闆可以盡量把時間空下來，好嗎？"
L20_1.m_Talk_THA = "ดังนั้นฉันอยากให้คุณเข้าร่วมการประชุมสุดสัปดาห์นี้"
L20_1.m_Talk_VTN = "Thế nên tôi muốn anh tham dự hội nghị cuối tuần này."
L20_1.m_Talk_SCN = "所以，我希望你能空出下周末的日程。"
L20_1.m_Talk_DEU = "So I want you to attend the conference this weekend."
L20_1.m_Talk_FRA = "So I want you to attend the conference this weekend."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "COUNTERCASE_ALPHA_JIA_NORMAL_4@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 31414
L21_1.m_CutScenStrID = "COUNTERCASE_ALPHA_JIA_NORMAL_4"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_SURPRISE"
L21_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L21_1.m_Pos = "R"
L21_1.m_Talk_KOREA = "대체 누군가! 이런 허례허식을 만들어 둔 인간이!"
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "いったい誰が！　こんな無意味な慣例を作ったのだ！"
L21_1.m_Talk_ENG = "I say, we should get rid of all the empty formalities and vanity."
L21_1.m_Talk_TWN = "到底是誰！哪個可惡的傢伙！搞這種繁文縟節幹嘛！"
L21_1.m_Talk_THA = "ผมว่าเราควรจะกำจัดพิธีรีตรองและความโอหังอันว่างเปล่าทั้งหมดทิ้ง"
L21_1.m_Talk_VTN = "Tôi nói này, chúng ta nên loại bỏ tất cả những thủ tục trống rỗng và phù phiếm này."
L21_1.m_Talk_SCN = "到底是谁！是谁在搞这种形式主义啊！"
L21_1.m_Talk_DEU = "I say, we should get rid of all the empty formalities and vanity."
L21_1.m_Talk_FRA = "I say, we should get rid of all the empty formalities and vanity."
L22_1 = {}
L22_1.m_CutScenKey_Talk = "COUNTERCASE_ALPHA_JIA_NORMAL_4@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 31414
L22_1.m_CutScenStrID = "COUNTERCASE_ALPHA_JIA_NORMAL_4"
L22_1.m_bWaitClick = true
