L22_1.m_Face = "UNIT_LAUGH"
L22_1.m_CharStrID = "LEESOOYEON_COFFIN_NULL_NULL"
L22_1.m_Pos = "L"
L22_1.m_Talk_KOREA = "……본인이 가장 잘 알고 계셔야죠."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "……それは本人が一番知っているのでは？"
L22_1.m_Talk_ENG = "Of which you should know the best above anyone else."
L22_1.m_Talk_TWN = "……這個你本人應該最清楚吧？"
L22_1.m_Talk_THA = "ซึ่งเป็นเรื่องที่คุณน่าจะรู้ดีกว่าใครนี่คะ"
L22_1.m_Talk_VTN = "Trong số tất cả mọi người, anh là người hiểu rõ nhất."
L22_1.m_Talk_SCN = "……你自己应该最清楚吧。"
L22_1.m_Talk_DEU = "Of which you should know the best above anyone else."
L22_1.m_Talk_FRA = "Of which you should know the best above anyone else."
L23_1 = {}
L23_1.m_CutScenKey_Talk = "COUNTERCASE_ALPHA_JIA_NORMAL_4@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 31414
L23_1.m_CutScenStrID = "COUNTERCASE_ALPHA_JIA_NORMAL_4"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_PRIDE"
L23_1.m_CharStrID = "MACHINEGAP_COFFIN_NULL_NULL"
L23_1.m_Pos = "R"
L23_1.m_Talk_KOREA = "잠깐, 그럼 사장이 주말 출근을 하는데 자네도 동행하는 거겠지?"
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "待てよ、社長が週末に出勤するんだ。もちろん君も同行するのだろう？"
L23_1.m_Talk_ENG = "So you’re accompanying me to the conference, right? It’s official business."
L23_1.m_Talk_TWN = "等等！老闆週末要上班的話，那你也應該要陪同吧？"
L23_1.m_Talk_THA = "คุณจะไปร่วมการประชุมกับผมใช่มั้ย? มันคือธุระทางการ"
L23_1.m_Talk_VTN = "Thế cô sẽ đi cùng tôi đến hội nghị chứ? Đó là công việc kinh doanh chính thức."
L23_1.m_Talk_SCN = "等等，那老板在周末上班，你也得同行才对吧？"
L23_1.m_Talk_DEU = "So you’re accompanying me to the conference, right? It’s official business."
L23_1.m_Talk_FRA = "So you’re accompanying me to the conference, right? It’s official business."
