L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "様々なものを食べ、知見を広げなさいと。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "That I have to try various types of food to broaden my perspectives."
L43_1.m_Talk_ENG = L44_1
L44_1 = "要品嘗不同類型的食物增廣見聞。"
L43_1.m_Talk_TWN = L44_1
