L46_1 = "<color=#ffd34c>황금 머신갑 레인저 에디션</color>의 가치에 걸맞은 식사를 해주지 않으면 곤란하네, 지아 양."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "<color=#ffd34c>黄金マシーン甲レンジャーエディション</color>の価値に見合う食事をしてもらわないと困るよ、ユイ君。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "You can’t think a burger is a equal value trade for the precious <color=#ffd34c>Gold Machine G.A.P. Ranger Edition</color>."
