L46_1 = "<color=#ffd34c>黃金機械戰士限量版</color>這麼珍貴，你選這麼便宜的東西，這樣我怎麼好意思呢？"
L45_1.m_Talk_TWN = L46_1
L46_1 = "คุณจะมองว่าเบอร์เกอร์เป็นการแลกเปลี่ยนที่เท่าเทียมกับ<color=#ffd34c>แมชชีน G.A.P. ทองเวอร์ชันยิงจู่โจม</color>อันเลอค่าไม่ได้นะ"
L45_1.m_Talk_THA = L46_1
L46_1 = "Cô không thể nghĩ rằng một chiếc burger có giá trị ngang với <color=#ffd34c> Máy G.A.P. Vàng Phiên Bản Lính Cơ Động</color> được."
L45_1.m_Talk_VTN = L46_1
L46_1 = "这个与<color=#ffd34c>黄金机械甲突击队员特别版</color>的价值差太多了，这太不好意思了，沈佳。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "You can’t think a burger is a equal value trade for the precious <color=#ffd34c>Gold Machine G.A.P. Ranger Edition</color>."
