L14_1 = "지아 양, 햄버거는 포장만 벗겨서 바로 먹으면 된다네. 그래서 패스트푸드지."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "ユイ君、ハンバーガーは包み紙を剥がして、そのまま食べるものさ。だからファストフードと呼ぶのだよ。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Jia, you don’t need cutlery for a burger. You eat it with your hands. That’s why it’s called fast food."
L13_1.m_Talk_ENG = L14_1
L14_1 = "沈佳，只需要把漢堡外的包裝紙拆開就可以吃囉！所以才叫速食的嘛～"
L13_1.m_Talk_TWN = L14_1
L14_1 = "เจีย เบอร์เกอร์ไม่ต้องใช้มีดกับส้อมนะ ต้องกินด้วยมือเปล่า เพราะงั้นคนถึงเรียกมันว่าอาหารจานด่วนไง"
L13_1.m_Talk_THA = L14_1
L14_1 = "Jia, cô không cần dao nĩa cho một chiếc burger. Phải ăn nó bằng tay. Đó là lí do chúng được gọi là đồ ăn nhanh."
L13_1.m_Talk_VTN = L14_1
L14_1 = "哈哈，汉堡只要剥开包装就可以吃了。所以才叫快餐啊。"
