L8_1 = "COUNTERCASE_ALPHA_JIA_NORMAL_4@157#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 31414
L7_1.m_CutScenStrID = "COUNTERCASE_ALPHA_JIA_NORMAL_4"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "JIA_ALPHA_NULL_NULL"
L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "L"
L8_1 = "많은 사람이 열광하는 것에는 분명 그럴 만한 이유가 있다고."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "多くの人が熱狂するものには、必ずそれ相応の理由があると。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "When lots of people are fond of something, there must a reason for it."
L7_1.m_Talk_ENG = L8_1
L8_1 = "受到許多人喜愛的東西，一定有他的道理在的。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "เวลาที่คนจำนวนมากชอบอะไรสักอย่างแปลว่ามันต้องมีสาเหตุ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Khi nhiều người thích một thứ gì đó, thì phải có lý do của nó."
L7_1.m_Talk_VTN = L8_1
L8_1 = "受到众人追捧的都是有原因的。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "When lots of people are fond of something, there must a reason for it."
L7_1.m_Talk_DEU = L8_1
L8_1 = "When lots of people are fond of something, there must a reason for it."
L7_1.m_Talk_FRA = L8_1
