L8_1.m_Pos = "L"
L8_1.m_Crash = 20
L9_1 = "저도 평범한 사람들이 좋아하는 영화가 어떤 영화인지 알고 싶어요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "私も一般の方々が好む映画がどのようなものか知りたいです。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "I want to know which movies people enjoy."
L8_1.m_Talk_ENG = L9_1
L9_1 = "我也想知道，普通人喜歡的是哪種電影。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "ฉันอยากรู้ว่าคนชอบหนังแบบไหนกัน"
L8_1.m_Talk_THA = L9_1
L9_1 = "Tôi muốn biết mọi người thích bộ phim nào."
L8_1.m_Talk_VTN = L9_1
L9_1 = "所以我想知道，普通人喜欢的电影到底是什么样的电影。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "I want to know which movies people enjoy."
L8_1.m_Talk_DEU = L9_1
L9_1 = "I want to know which movies people enjoy."
L8_1.m_Talk_FRA = L9_1
