L9_1.m_Pos = "R"
L10_1 = "할이버님의 말씀을 잘 듣는 착한 아이도 좋지만, 가끔은 지아 양 본인이 정말로 원하는 걸 해 보는 것도 좋지 않겠나?"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "お祖父様の言いつけを守るいい子も結構だが、たまには自分が心から望むことをしてみてもいいんじゃないか？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "It’s nice that you remember what your grandfather said, but sometimes, you have to do something that YOU want."
L9_1.m_Talk_ENG = L10_1
L10_1 = "聽爺爺的話當個乖孩子很好，但偶爾照你自己真正的想法去做也很好不是嗎？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "การที่คุณจำสิ่งที่คุณปู่สอนได้เป็นเรื่องที่ดีนะ แต่บางครั้งคุณก็ต้องทำสิ่งคุณเองต้องการด้วย"
L9_1.m_Talk_THA = L10_1
L10_1 = "Thật tuyệt khi nhớ những gì ông cô đã nói, nhưng đôi khi cô phải làm điều gì đó mà CÔ muốn."
L9_1.m_Talk_VTN = L10_1
L10_1 = "虽然做一个听爷爷话的好孩子也不错，但沈佳你偶尔也要做自己想做的事，不是吗？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "It’s nice that you remember what your grandfather said, but sometimes, you have to do something that YOU want."
L9_1.m_Talk_DEU = L10_1
L10_1 = "It’s nice that you remember what your grandfather said, but sometimes, you have to do something that YOU want."
L9_1.m_Talk_FRA = L10_1
