L26_1.m_Talk_THA = L27_1
L27_1 = "Tôi kiếm anh nãy giờ, và anh thì ở đây."
L26_1.m_Talk_VTN = L27_1
L27_1 = "我找了一圈，原来你们在这儿？"
L26_1.m_Talk_SCN = L27_1
L27_1 = "I was looking all over for you, and you’re here."
